# Check for each bg cell: what's its 8-neighborhood in terms of 6s?
def count_neighboring_sixes(r, c, arr):
    count = 0
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
