def count_n6(r, c):
    return sum(1 for dr in [-1, 0, 1] for dc in [-1, 0, 1] 
               if (dr==0 and dc==0) or (0 <= r+dr < inp_arr.shape[0] and 0 <= c+dc < inp_arr.shape[1] and inp_arr[r+dr,c+dc]==6))

def classify_cell(r, c):
    if r == 0 or r == inp_arr.shape[0]-1:
        return "horizontal_edge"
    elif c == 0 or c == inp_arr.shape[1]-1:
        return "vertical_edge"
    else:
        return "interior"

